function rows(sheet){var c=sheet&&sheet.content;if(!c||c.length<2)return[];var idx={};c[0].forEach(function(h,i){if(h&&h!=='row_id'&&h!=='行号')idx[h]=i;});return c.slice(1).map(function(r){var o={};Object.keys(idx).forEach(function(n){o[n]=r[idx[n]];});return o;});}
